() => {
  const btn = Array.from(document.querySelectorAll('button')).find(b => (b.getAttribute('aria-label')||b.textContent||'').includes('收起侧边栏'));
  if (!btn) return {found: false};
  btn.click();
  return {found: true, label: btn.getAttribute('aria-label') || btn.textContent};
}

() => {
  const aside = document.querySelector('aside, [class*=sidebar], nav');
  const buttons = Array.from(document.querySelectorAll('button')).slice(0, 20).map(b => ({
    aria: b.getAttribute('aria-label'),
    title: b.getAttribute('title'),
    text: (b.textContent||'').trim().slice(0,30),
    cls: (b.className||'').slice(0,60)
  }));
  return {asideFound: !!aside, buttons};
}

() => {
  const btn = document.querySelector('button[title="收起侧边栏"]');
  if (!btn) return {found: false};
  btn.click();
  return {found: true, clicked: true};
}

() => {
  const aside = document.querySelector('aside, [class*=sidebar]');
  const collapseBtn = document.querySelector('button[title="收起侧边栏"], button[title="展开侧边栏"]');
  // Find the sidebar container - look for the complementary element
  const complementary = document.querySelector('[role="complementary"]') || aside;
  let el = complementary;
  let rect = el ? el.getBoundingClientRect() : null;
  // walk up to find the actual width-constrained container
  return {
    asideTag: aside ? aside.tagName : null,
    asideClass: aside ? aside.className.slice(0, 120) : null,
    asideWidth: rect ? rect.width : null,
    collapseBtnTitle: collapseBtn ? collapseBtn.getAttribute('title') : null
  };
}

() => {
  const aside = document.querySelector('aside');
  const btns = aside.querySelectorAll('button');
  // btns[0] = expand toggle, btns[1] = first menu item (智能问答与查询)
  const target = btns[1];
  if (!target) return {found: false};
  const rect = target.getBoundingClientRect();
  const cx = rect.left + rect.width/2, cy = rect.top + rect.height/2;
  const opts = {bubbles: true, cancelable: true, view: window, clientX: cx, clientY: cy};
  target.dispatchEvent(new MouseEvent('mouseover', opts));
  target.dispatchEvent(new MouseEvent('mouseenter', {...opts, bubbles: false}));
  target.dispatchEvent(new MouseEvent('mousemove', opts));
  return {found: true, rect: {x: rect.x, y: rect.y, w: rect.width, h: rect.height}, idx: 1, count: btns.length};
}

async () => {
  await new Promise(r => setTimeout(r, 600));
  // Look for tooltip elements
  const candidates = Array.from(document.querySelectorAll('[role="tooltip"], [class*="tooltip"], [class*="Tooltip"]'));
  const results = candidates.map(el => ({
    cls: el.className.slice(0, 100),
    text: (el.textContent||'').trim().slice(0, 100),
    visible: el.offsetParent !== null,
    rect: el.getBoundingClientRect()
  }));
  // also check for any new fixed/absolute elements containing the title text
  const all = Array.from(document.querySelectorAll('body *')).filter(el => 
    el.children.length === 0 && (el.textContent||'').includes('智能问答与查询')
  ).map(el => ({tag: el.tagName, cls: (el.className||'').toString().slice(0,80)}));
  return {tooltips: results, titleNodes: all.slice(0,5)};
}

() => {
  const span = Array.from(document.querySelectorAll('span')).find(el => (el.textContent||'').trim() === '智能问答与查询');
  if (!span) return {found: false};
  // walk up to find the tooltip container
  let node = span, chain = [];
  for (let i = 0; i < 6 && node; i++) {
    const r = node.getBoundingClientRect ? node.getBoundingClientRect() : null;
    chain.push({
      tag: node.tagName,
      cls: (node.className||'').toString().slice(0, 120),
      rect: r ? {x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height)} : null
    });
    node = node.parentElement;
  }
  return {found: true, chain};
}

() => {
  const aside = document.querySelector('aside');
  return {
    asideClass: aside ? aside.className.slice(0, 80) : null,
    visibility: document.visibilityState
  };
}

() => {
  const aside = document.querySelector('aside');
  const asideCS = getComputedStyle(aside);
  const btns = aside.querySelectorAll('button');
  // button[1] = 智能问答与查询, button[6] = 数据源与 Schema (button[0] = expand toggle)
  const inspect = (btn) => {
    if (!btn) return null;
    const tip = btn.querySelector('span.pointer-events-none');
    if (!tip) return {hasTip: false};
    const parts = Array.from(tip.querySelectorAll('span')).map(s => ({
      text: (s.textContent||'').trim(),
      cls: (s.className||'').toString()
    }));
    const tipCS = getComputedStyle(tip);
    const btnCS = getComputedStyle(btn);
    const r = btn.getBoundingClientRect();
    return {
      hasTip: true,
      tipClass: (tip.className||'').toString(),
      tipParts: parts,
      tipPosition: {pos: tipCS.position, left: tipCS.left, zIndex: tipCS.zIndex, display: tipCS.display, pointerEvents: tipCS.pointerEvents},
      btnRect: {x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height)},
      btnOverflow: btnCS.overflow
    };
  };
  return {
    asideOverflow: asideCS.overflow,
    asideOverflowX: asideCS.overflowX,
    asideWidth: asideCS.width,
    menu1: inspect(btns[1]),
    menu6: inspect(btns[6])
  };
}

() => {
  const aside = document.querySelector('aside');
  const btns = aside.querySelectorAll('button');
  const results = {};
  [1, 6].forEach(idx => {
    const btn = btns[idx];
    const tip = btn.querySelector('span.pointer-events-none');
    // simulate group-hover: force display block
    const orig = tip.style.display;
    tip.style.display = 'block';
    const r = tip.getBoundingClientRect();
    const cs = getComputedStyle(tip);
    tip.style.display = orig;
    results['menu'+idx] = {
      rect: {x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), right: Math.round(r.right)},
      withinViewport: r.right <= window.innerWidth && r.x >= 0,
      viewportW: window.innerWidth,
      bg: cs.backgroundColor, border: cs.borderColor, shadow: cs.boxShadow.slice(0,40),
      asideRightEdge: 64,
      startsRightOfSidebar: r.x >= 63
    };
  });
  return results;
}
